parameters.jsCode:
// ---- shared chrome -------------------------------------------------------
// Inline styles only: Gmail strips <style> blocks. Coral #e35d5d is the brand
// accent from project-overview.md §25.2.
const brand = '#e35d5d';
const site = ($('Config').first().json.AMANTRIKA_SITE_URL || 'https://amantrika.com').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const stat = (label, value) => `<div style="display:inline-block;min-width:118px;margin:0 14px 14px 0;"><div style="font-size:26px;font-weight:600;color:#1f1a19;line-height:1.1;">${value}</div><div style="font-size:12px;color:#8a7d7a;text-transform:uppercase;letter-spacing:.06em;margin-top:3px;">${label}</div></div>`;
const shell = (heading, bodyHtml, ctaLabel, ctaHref, footNote) => `
<div style="margin:0;padding:24px 12px;background:#faf7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px 28px;border:1px solid #f0e6e2;">
    <div style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:${brand};font-weight:600;">Amantrika</div>
    <h1 style="margin:14px 0 18px;font-size:22px;line-height:1.32;color:#1f1a19;font-weight:600;">${heading}</h1>
    <div style="font-size:15px;line-height:1.65;color:#453c3a;">${bodyHtml}</div>
    ${ctaHref ? `<div style="margin:26px 0 6px;"><a href="${ctaHref}" style="display:inline-block;background:${brand};color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-weight:600;font-size:15px;">${ctaLabel}</a></div>` : ''}
    ${footNote ? `<p style="margin:24px 0 0;font-size:13px;line-height:1.6;color:#8a7d7a;">${footNote}</p>` : ''}
  </div>
  <div style="max-width:560px;margin:16px auto 0;text-align:center;font-size:12px;color:#a29793;">
    Amantrika · digital invitations for Indian celebrations<br/>
    <a href="${site}" style="color:#a29793;">${site.replace(/^https?:\/\//, '')}</a>
  </div>
</div>`;
// No /unsubscribe route exists in the app yet, so RFC 8058's mailto form is
// used. See "Follow-ups" in n8n/README.md.
const unsub = (scope) => 'mailto:' + ($('Config').first().json.AMANTRIKA_UNSUBSCRIBE_MAILBOX || 'unsubscribe@amantrika.com')
  + '?subject=' + encodeURIComponent('unsubscribe ' + scope);
const d = $json;

const url  = site + '/invite/' + encodeURIComponent(d.slug);
const dash = site + '/dashboard/' + encodeURIComponent(d.event_id);

// Pre-filled WhatsApp deep link. NOT the WhatsApp API — project-overview.md §18
// permits batched deep links and forbids unofficial automation. This just opens
// the host's own WhatsApp with the message ready.
const waText = `${d.title}\n${d.event_date_long ? d.event_date_long.replace(/\s+/g, ' ').trim() : ''}\n\n${url}`;
const waLink = 'https://wa.me/?text=' + encodeURIComponent(waText);
const qr = 'https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=8&data=' + encodeURIComponent(url);
const shareKit = `
  <div style="background:#faf7f5;border-radius:12px;padding:20px;margin:0 0 18px;text-align:center;">
    <div style="font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:14px;color:#1f1a19;word-break:break-all;margin:0 0 14px;">${esc(url)}</div>
    <a href="${waLink}" style="display:inline-block;background:#25d366;color:#ffffff;text-decoration:none;padding:11px 22px;border-radius:8px;font-weight:600;font-size:14px;">Share on WhatsApp</a>
  </div>
  <div style="text-align:center;margin:0 0 18px;">
    <img src="${qr}" width="150" height="150" alt="QR code linking to ${esc(d.title)}" style="border-radius:10px;border:1px solid #f0e6e2;" />
    <div style="font-size:12px;color:#8a7d7a;margin-top:7px;">Print this on a card. It opens the invitation.</div>
  </div>`;

let heading, bodyHtml, subject, footNote;

if (d.variant === 'confirmation') {
  heading = 'Your invitation is live';
  subject = 'Your invitation is live \u2014 ' + d.title;
  bodyHtml = `
    <p style="margin:0 0 18px;">Hi ${esc(d.owner_name)}, <strong>${esc(d.title)}</strong> is published. One link, and it works on every phone.</p>
    ${shareKit}
    ${d.is_watermarked ? `<div style="background:#fff5f3;border-left:3px solid ${brand};padding:12px 16px;border-radius:6px;margin:0 0 4px;">
        <strong>You are on the free plan.</strong> Your invitation carries an Amantrika mark, and links shared to WhatsApp show as plain text rather than a rich preview card. Upgrading removes both.
      </div>` : ''}`;
  footNote = d.is_watermarked
    ? `See what each plan includes at <a href="${site}/pricing" style="color:${brand};">${site.replace(/^https?:\/\//, '')}/pricing</a>.`
    : null;
} else {
  heading = 'Everything you need to share it';
  subject = 'Share ' + d.title;
  bodyHtml = `
    <p style="margin:0 0 18px;">Hi ${esc(d.owner_name)}, your receipt is already in your inbox. This one is the sharing kit for <strong>${esc(d.title)}</strong>.</p>
    ${shareKit}
    <p style="margin:0;">${Number(d.guests_added) > 0
      ? 'You have <strong>' + d.guests_added + '</strong> guests on your list. Personalised links \u2014 one per guest, so their RSVP is pre-filled \u2014 are on your dashboard.'
      : 'Add your guest list on the dashboard to get personalised links, one per guest, so their RSVP arrives pre-filled.'}</p>`;
  footNote = null;
}

return { json: {
  dedupe_key: d.dedupe_key,
  to: d.owner_email,
  stored: {
    event_id: d.event_id, slug: d.slug, title: d.title, plan_code: d.plan_code,
    variant: d.variant, is_watermarked: d.is_watermarked, url,
    dedupe_key: d.dedupe_key,
    subject,
    html: shell(heading, bodyHtml, 'Open your dashboard', dash, footNote),
    text: heading + '\n\n' + d.title + '\n' + url + '\n\nDashboard: ' + dash,
  },
} };

parameters.jsonBody:
={{ JSON.stringify({
  from: $('Config').first().json.AMANTRIKA_EMAIL_FROM,
  to: [ $json.recipient ],
  subject: $json.payload.subject,
  html: $json.payload.html,
  text: $json.payload.text,
  headers: $json.payload.unsubscribe
    ? { 'List-Unsubscribe': '<' + $json.payload.unsubscribe + '>',
        'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' }
    : {}
}) }}
